/**
 * Playwright-as-transport for chatgpt.com.
 *
 * Why Playwright instead of raw fetch (like DeepSeek):
 *   ChatGPT is fronted by Cloudflare + a custom "sentinel" anti-bot system
 *   that gates every /backend-api/* call. Cloudflare fingerprints the TLS
 *   handshake and HTTP/2 frame ordering; raw Node fetch fails the check.
 *   Sentinel additionally requires a proof-of-work token, an Arkose token
 *   on some accounts, and a Turnstile token after challenges. All three
 *   are produced by JS inside the chatgpt.com page.
 *
 *   Instead of replicating that JS in Node (which OpenAI rotates every few
 *   weeks), we keep a real headless Chrome open, navigated to chatgpt.com,
 *   and tunnel every API call through `page.evaluate(fetch)`. The browser
 *   handles cookies, TLS, sentinel, and PoW on our behalf. Streaming is
 *   tunneled back via `page.exposeFunction()`.
 *
 * Lifecycle:
 *   - First call to `getPage()` boots a persistent Chrome (~2s) and parks
 *     it on https://chatgpt.com/. Subsequent calls reuse it.
 *   - The browser stays alive for the process lifetime unless `close()`
 *     is called explicitly (e.g. on graceful shutdown).
 *   - Persistent profile lives at `.chatgpt-research/chrome-profile` in the
 *     consumer's cwd — same convention as the DeepSeek extractor.
 */

import { existsSync, mkdirSync } from "node:fs";
import { join }                  from "node:path";
import type {
  BrowserContext,
  Page,
} from "playwright";

const TARGET = "https://chatgpt.com";

// ── Errors ────────────────────────────────────────────────────────────────
export class ChatGPTTransportError extends Error {
  constructor(msg: string, public readonly cause?: unknown) {
    super(msg);
    this.name = "ChatGPTTransportError";
  }
}
export class ChatGPTAuthError extends ChatGPTTransportError {
  constructor(m: string, c?: unknown) { super(m, c); this.name = "ChatGPTAuthError"; }
}
export class ChatGPTNotSignedInError extends ChatGPTAuthError {
  constructor() {
    super(
      "Not signed into chatgpt.com — run: npm run chatgpt:setup (opens a window for sign-in).",
    );
    this.name = "ChatGPTNotSignedInError";
  }
}

// ── Module singleton ──────────────────────────────────────────────────────
let _ctx: BrowserContext | null = null;
let _page: Page | null = null;
let _bootPromise: Promise<{ ctx: BrowserContext; page: Page }> | null = null;

interface BootOpts {
  /** Force a visible window (default false). Useful for first-time sign-in. */
  headed?: boolean;
}

function consumerRoot(): string {
  return process.env.AI_PROVIDERS_CONSUMER_ROOT ?? process.cwd();
}

function profileDir(): string {
  return join(consumerRoot(), ".chatgpt-research", "chrome-profile");
}

async function boot(opts: BootOpts = {}): Promise<{ ctx: BrowserContext; page: Page }> {
  if (_ctx && _page) return { ctx: _ctx, page: _page };
  if (_bootPromise) return _bootPromise;

  _bootPromise = (async () => {
    const profile = profileDir();
    mkdirSync(profile, { recursive: true });

    const { chromium } = await import("playwright");
    const ctx = await chromium.launchPersistentContext(profile, {
      channel:   "chrome",
      headless:  !opts.headed,
      viewport:  { width: 1366, height: 768 },
      locale:    "en-US",
      timezoneId: "Asia/Riyadh",
      args: [
        "--disable-blink-features=AutomationControlled",
        "--exclude-switches=enable-automation",
        "--no-first-run",
        "--no-default-browser-check",
      ],
      ignoreDefaultArgs: ["--enable-automation"],
    });

    // Light anti-detection — removes the `navigator.webdriver = true` giveaway.
    await ctx.addInitScript(() => {
      Object.defineProperty(navigator, "webdriver", { get: () => undefined });
      Object.defineProperty(navigator, "languages",  { get: () => ["en-US", "en", "ar"] });
    });

    const page = ctx.pages()[0] ?? await ctx.newPage();
    await page.goto(TARGET, { waitUntil: "domcontentloaded", timeout: 45_000 });
    // Let the page settle so cookies + service worker register before first API call.
    await page.waitForLoadState("networkidle", { timeout: 20_000 }).catch(() => { /* best-effort */ });

    _ctx = ctx;
    _page = page;
    return { ctx, page };
  })();

  try {
    return await _bootPromise;
  } finally {
    _bootPromise = null;
  }
}

export async function getPage(opts: BootOpts = {}): Promise<Page> {
  const { page } = await boot(opts);
  return page;
}

export async function close(): Promise<void> {
  if (_ctx) {
    await _ctx.close().catch(() => { /* ignore */ });
    _ctx = null;
    _page = null;
  }
}

// ── Verify sign-in ────────────────────────────────────────────────────────
export interface SessionInfo {
  accessToken: string;
  user: { id: string; email?: string; name?: string };
  expires: string;
}

/** Hit /api/auth/session via the page. Returns null if not signed in. */
export async function getSession(opts: BootOpts = {}): Promise<SessionInfo | null> {
  const page = await getPage(opts);
  const result = await page.evaluate(async () => {
    try {
      const r = await fetch("/api/auth/session", {
        credentials: "include",
        headers: { accept: "application/json" },
      });
      if (!r.ok) return { ok: false as const, status: r.status };
      const body = await r.json();
      // When signed-out, the endpoint returns {} (200 OK). Treat absence of
      // accessToken as not-signed-in.
      if (!body || !body.accessToken) return { ok: false as const, status: 200, body };
      return { ok: true as const, body };
    } catch (e) {
      return { ok: false as const, status: 0, error: (e as Error).message };
    }
  });
  if (!result.ok) return null;
  const b = result.body as { accessToken: string; user: { id: string; email?: string; name?: string }; expires: string };
  return { accessToken: b.accessToken, user: b.user, expires: b.expires };
}

/** Throws if not signed in. */
export async function requireSession(opts: BootOpts = {}): Promise<SessionInfo> {
  const s = await getSession(opts);
  if (!s) throw new ChatGPTNotSignedInError();
  return s;
}

// ── In-page JSON request ──────────────────────────────────────────────────
export interface PageFetchInit {
  method?: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
  headers?: Record<string, string>;
  /** JSON-serializable body. */
  body?: unknown;
}

/**
 * Run `fetch(path, init)` inside the page's origin and return the parsed
 * JSON response. Throws ChatGPTTransportError on network/parse failure
 * and ChatGPTAuthError on 401/403.
 */
export async function apiJson<T = unknown>(path: string, init: PageFetchInit = {}): Promise<T> {
  const page = await getPage();
  const result = await page.evaluate(async (args) => {
    const { path: p, init: i } = args;
    try {
      const r = await fetch(p, {
        method: i.method ?? "GET",
        credentials: "include",
        headers: {
          accept: "*/*",
          "content-type": "application/json",
          ...(i.headers ?? {}),
        },
        body: i.body !== undefined ? JSON.stringify(i.body) : undefined,
      });
      const txt = await r.text();
      return { ok: r.ok, status: r.status, statusText: r.statusText, body: txt };
    } catch (e) {
      return { ok: false, status: 0, statusText: "fetch failed", body: (e as Error).message };
    }
  }, { path, init });

  if (result.status === 401 || result.status === 403) {
    throw new ChatGPTAuthError(`${path} → ${result.status} (session expired or sentinel rejected)`);
  }
  if (!result.ok) {
    throw new ChatGPTTransportError(`${path} → HTTP ${result.status}: ${result.body.slice(0, 300)}`);
  }
  try {
    return JSON.parse(result.body) as T;
  } catch {
    throw new ChatGPTTransportError(`${path} → non-JSON response: ${result.body.slice(0, 300)}`);
  }
}

// ── In-page streaming request (SSE) ───────────────────────────────────────
export interface StreamOpts extends PageFetchInit {
  /** Called for every chunk of the raw response body as it arrives. */
  onChunk: (text: string) => void;
  signal?: AbortSignal;
}

/**
 * Stream a POST request from within the page, forwarding every chunk back
 * to Node via `page.exposeFunction`. Returns when the page-side fetch
 * resolves (i.e. the server closed the stream). The opaque body parts are
 * delivered verbatim — caller is responsible for SSE framing.
 *
 * Why a per-call function name: `exposeFunction` is bound globally and
 * cannot be redefined, so we generate a fresh unique name per call and
 * unbind it after by replacing with a no-op (Playwright lacks an
 * `unexposeFunction`). The bridge is single-use.
 */
let _bridgeCounter = 0;

export async function streamApi(path: string, opts: StreamOpts): Promise<{ status: number; statusText: string }> {
  const page = await getPage();
  const bridgeName = `__ai_stream_${++_bridgeCounter}_${Date.now().toString(36)}`;

  await page.exposeFunction(bridgeName, (chunk: string) => {
    try { opts.onChunk(chunk); } catch { /* listener errors must not abort */ }
  });

  const abortName = `${bridgeName}_abort`;
  let abortCb: (() => void) | null = null;
  if (opts.signal) {
    await page.exposeFunction(abortName, () => { /* receives nothing; page polls */ });
    abortCb = () => {
      void page.evaluate((n) => {
        const w = window as unknown as Record<string, unknown>;
        w[n + "_aborted"] = true;
      }, bridgeName).catch(() => { /* ignore */ });
    };
    if (opts.signal.aborted) abortCb();
    else opts.signal.addEventListener("abort", abortCb, { once: true });
  }

  try {
    const result = await page.evaluate(async (args) => {
      const { path: p, init: i, bridgeName: bn } = args;
      const w = window as unknown as Record<string, unknown>;
      const cb = w[bn] as (s: string) => Promise<void>;
      const aborted = (): boolean => w[bn + "_aborted"] === true;
      try {
        const r = await fetch(p, {
          method: i.method ?? "POST",
          credentials: "include",
          headers: {
            accept: "text/event-stream",
            "content-type": "application/json",
            ...(i.headers ?? {}),
          },
          body: i.body !== undefined ? JSON.stringify(i.body) : undefined,
        });
        if (!r.body) {
          return { status: r.status, statusText: r.statusText, error: "no body stream" };
        }
        // For non-2xx, drain as text and return so caller can classify.
        if (!r.ok) {
          const txt = await r.text();
          await cb(`__HTTP_ERROR__:${r.status}:${txt}`);
          return { status: r.status, statusText: r.statusText };
        }
        const reader = r.body.getReader();
        const dec = new TextDecoder();
        for (;;) {
          if (aborted()) {
            try { await reader.cancel(); } catch { /* ignore */ }
            return { status: r.status, statusText: r.statusText, error: "aborted" };
          }
          const { value, done } = await reader.read();
          if (done) break;
          await cb(dec.decode(value, { stream: true }));
        }
        return { status: r.status, statusText: r.statusText };
      } catch (e) {
        return { status: 0, statusText: "fetch failed", error: (e as Error).message };
      }
    }, { path, init: opts, bridgeName });

    if (result.error && result.error !== "aborted") {
      throw new ChatGPTTransportError(`${path} stream → ${result.error}`);
    }
    if (result.status === 401 || result.status === 403) {
      throw new ChatGPTAuthError(`${path} → ${result.status} (session expired or sentinel rejected)`);
    }
    return { status: result.status, statusText: result.statusText };
  } finally {
    if (abortCb && opts.signal) opts.signal.removeEventListener("abort", abortCb);
    // Replace bridge with a no-op so future page errors don't trigger the
    // real callback. We cannot unbind, but we can neuter.
    await page.evaluate((bn) => {
      const w = window as unknown as Record<string, unknown>;
      w[bn] = () => Promise.resolve();
      delete w[bn + "_aborted"];
    }, bridgeName).catch(() => { /* ignore */ });
  }
}
